WITH session_summary AS (SELECT session_id, SUM(CASE WHEN event_type = 'page_view' THEN 1 ELSE 0 END) AS page_view_count, MAX(duration_sec) AS max_duration_sec FROM web_events WHERE event_type = 'page_view' GROUP BY session_id) SELECT s.browser, ss.page_view_count, ss.max_duration_sec FROM sessions s INNER JOIN session_summary ss ON s.id = ss.session_id WHERE ss.max_duration_sec >= 140;
